class ProductRow extends DataClass implements Insertable<ProductRow> {
  final String id;
  final String shopId;
  final String name;
  final String category;
  final int costPriceMinor;
  final int suggestedSellPriceMinor;
  final double qty;
  final FundSourceType fundSourceType;
  final String? fundSourceInvestorId;
  final bool isRentable;
  final String? barcode;
  final String? sku;

  /// Only meaningful when [isRentable] is true — the tier lookup at
  /// rent-issue time (`notes/business_logic.md` §জ) is keyed by this.
  /// Nullable for the same reason [isRentable] is a general flag rather
  /// than a category-restricted column: most products never rent, so
  /// most rows never set this.
  final int? pageCount;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final DateTime syncedAt;
  const ProductRow({
    required this.id,
    required this.shopId,
    required this.name,
    required this.category,
    required this.costPriceMinor,
    required this.suggestedSellPriceMinor,
    required this.qty,
    required this.fundSourceType,
    this.fundSourceInvestorId,
    required this.isRentable,
    this.barcode,
    this.sku,
    this.pageCount,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.syncedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['shop_id'] = Variable<String>(shopId);
    map['name'] = Variable<String>(name);
    map['category'] = Variable<String>(category);
    map['cost_price_minor'] = Variable<int>(costPriceMinor);
    map['suggested_sell_price_minor'] = Variable<int>(suggestedSellPriceMinor);
    map['qty'] = Variable<double>(qty);
    {
      map['fund_source_type'] = Variable<String>(
        $ProductsTable.$converterfundSourceType.toSql(fundSourceType),
      );
    }
    if (!nullToAbsent || fundSourceInvestorId != null) {
      map['fund_source_investor_id'] = Variable<String>(fundSourceInvestorId);
    }
    map['is_rentable'] = Variable<bool>(isRentable);
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || pageCount != null) {
      map['page_count'] = Variable<int>(pageCount);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['synced_at'] = Variable<DateTime>(syncedAt);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      shopId: Value(shopId),
      name: Value(name),
      category: Value(category),
      costPriceMinor: Value(costPriceMinor),
      suggestedSellPriceMinor: Value(suggestedSellPriceMinor),
      qty: Value(qty),
      fundSourceType: Value(fundSourceType),
      fundSourceInvestorId: fundSourceInvestorId == null && nullToAbsent
          ? const Value.absent()
          : Value(fundSourceInvestorId),
      isRentable: Value(isRentable),
      barcode: barcode == null && nullToAbsent
          ? const Value.absent()
          : Value(barcode),
      sku: sku == null && nullToAbsent ? const Value.absent() : Value(sku),
      pageCount: pageCount == null && nullToAbsent
          ? const Value.absent()
          : Value(pageCount),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      syncedAt: Value(syncedAt),
    );
  }

