      id: serializer.fromJson<String>(json['id']),
      shopId: serializer.fromJson<String>(json['shopId']),
      name: serializer.fromJson<String>(json['name']),
      category: serializer.fromJson<String>(json['category']),
      costPriceMinor: serializer.fromJson<int>(json['costPriceMinor']),
      suggestedSellPriceMinor: serializer.fromJson<int>(
        json['suggestedSellPriceMinor'],
      ),
      qty: serializer.fromJson<double>(json['qty']),
      fundSourceType: $ProductsTable.$converterfundSourceType.fromJson(
        serializer.fromJson<String>(json['fundSourceType']),
      ),
      fundSourceInvestorId: serializer.fromJson<String?>(
        json['fundSourceInvestorId'],
      ),
      isRentable: serializer.fromJson<bool>(json['isRentable']),
      barcode: serializer.fromJson<String?>(json['barcode']),
      sku: serializer.fromJson<String?>(json['sku']),
