class $$ShopsTableTableManager
    extends
        RootTableManager<
          _$AppDatabaseV2,
          $ShopsTable,
          ShopRow,
          $$ShopsTableFilterComposer,
          $$ShopsTableOrderingComposer,
          $$ShopsTableAnnotationComposer,
          $$ShopsTableCreateCompanionBuilder,
          $$ShopsTableUpdateCompanionBuilder,
          (ShopRow, $$ShopsTableReferences),
          ShopRow,
          PrefetchHooks Function({
            bool categoriesRefs,
            bool productsRefs,
            bool customersRefs,
            bool investorsRefs,
            bool investorRepaymentsRefs,
            bool legacySettlementsRefs,
            bool purchaseTripsRefs,
            bool salesRefs,
            bool duesRefs,
            bool rentPricingTiersRefs,
            bool rentTransactionsRefs,
            bool expensesRefs,
            bool ordersRefs,
            bool fixedAssetsRefs,
            bool quickCapturesRefs,
            bool cashLedgerEntriesRefs,
            bool stockMovementsRefs,
            bool auditLogEntriesRefs,
          })
        > {
  $$ShopsTableTableManager(_$AppDatabaseV2 db, $ShopsTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ShopsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ShopsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ShopsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> name = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ShopsCompanion(
                id: id,
                name: name,
                createdAt: createdAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String name,
                required DateTime createdAt,
                Value<int> rowid = const Value.absent(),
              }) => ShopsCompanion.insert(
                id: id,
                name: name,
                createdAt: createdAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) =>
                    (e.readTable(table), $$ShopsTableReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                categoriesRefs = false,
                productsRefs = false,
                customersRefs = false,
                investorsRefs = false,
                investorRepaymentsRefs = false,
                legacySettlementsRefs = false,
                purchaseTripsRefs = false,
                salesRefs = false,
                duesRefs = false,
                rentPricingTiersRefs = false,
                rentTransactionsRefs = false,
                expensesRefs = false,
                ordersRefs = false,
                fixedAssetsRefs = false,
                quickCapturesRefs = false,
                cashLedgerEntriesRefs = false,
                stockMovementsRefs = false,
                auditLogEntriesRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (categoriesRefs) db.categories,
                    if (productsRefs) db.products,
                    if (customersRefs) db.customers,
                    if (investorsRefs) db.investors,
                    if (investorRepaymentsRefs) db.investorRepayments,
                    if (legacySettlementsRefs) db.legacySettlements,
                    if (purchaseTripsRefs) db.purchaseTrips,
                    if (salesRefs) db.sales,
                    if (duesRefs) db.dues,
                    if (rentPricingTiersRefs) db.rentPricingTiers,
                    if (rentTransactionsRefs) db.rentTransactions,
                    if (expensesRefs) db.expenses,
                    if (ordersRefs) db.orders,
                    if (fixedAssetsRefs) db.fixedAssets,
                    if (quickCapturesRefs) db.quickCaptures,
